referenceSolutions.javascript:
function tallerKeycapsFirstQualifyingSlip(readings, k) {
  const a=readings; let out=[];
  out=Array(a.length).fill(0);const stack=[];for(let i=0;i<a.length;i++){while(stack.length&&a[stack[stack.length-1]]<a[i]){const j=stack.pop();out[j]=i-j;}stack.push(i);}
  return out.find(x=>x>=k)??-1;
}

